const footprints = $('1. Operating Footprint Check (/v1/company-footprint)').all();
const jobsList = $input.all();
const dossiers = [];
for (let i = 0; i < jobsList.length; i++) {
  const f = (footprints[i] && footprints[i].json) || {};
  const j = (jobsList[i] && jobsList[i].json) || {};
  const fp = f.footprint || {};
  const tech = f.tech_stack || {};
  const intent = f.hiring_intent || {};
  dossiers.push({
    json: {
      domain: f.domain || j.domain,
      sections_with_verified_data: (f.sections_with_data || []).join(', '),
      website_tags_status: fp.website_ad_or_analytics_tags || 'unknown',
      active_job_board: fp.job_board_with_open_roles || 'unknown',
      active_google_ads: fp.google_ads_transparency_records || 'unknown',
      ats_provider: j.ats_provider || intent.ats_provider || null,
      total_open_roles: j.total_jobs ?? intent.total_open_roles ?? 0,
      hiring_velocity_status: intent.hiring_status || 'unknown',
      hosting_and_cdn: (tech.hosting_cdn || []).join(', '),
      diligence_summary: `Verified sections: ${(f.sections_with_data || []).length}/3. Open roles: ${j.total_jobs ?? intent.total_open_roles ?? 0}.`
    }
  });
}
return dossiers;
